try {
  const { keywords, location, jobType, minSalary, _verifyMode } = params;

  // Check for anti-bot on initial page
  await page.checkAntiBot({ maxWait: 10000 });

  // Fill keywords
  await page.waitForSelector('#text-input-what', { timeout: 8000 });
  await page.randomDelay(800, 1500);
  await page.humanType('#text-input-what', keywords || '');
  await page.randomDelay(500, 1000);

  // Fill location
  if (location) {
    await page.humanType('#text-input-where', location);
    await page.randomDelay(500, 1000);
  }

  // Submit search
  await page.humanClick('button[type="submit"].yosegi-InlineWhatWhere-primaryButton');
  await page.waitForNavigation({ timeout: 15000 });
  await page.checkAntiBot({ maxWait: 10000 });
  await page.randomDelay(1500, 2500);

  // Apply job type filter if specified
  if (jobType) {
    const typeMap = {
      'fulltime': 'fulltime',
      'full-time': 'fulltime',
      'parttime': 'parttime',
      'part-time': 'parttime',
      'contract': 'contract',
      'temporary': 'temporary',
      'internship': 'internship'
    };
    const jtKey = typeMap[(jobType || '').toLowerCase()] || jobType.toLowerCase();
    const currentUrl = await page.url();
    const sep = currentUrl.includes('?') ? '&' : '?';
    await page.goto(currentUrl + sep + 'jt=' + jtKey);
    await page.waitForNavigation({ timeout: 15000 }).catch(() => {});
    await page.checkAntiBot({ maxWait: 10000 });
    await page.randomDelay(1500, 2500);
  }

  // Apply salary filter if specified
  if (minSalary) {
    const currentUrl = await page.url();
    const sep = currentUrl.includes('?') ? '&' : '?';
    // Indeed uses salary param like salary=$60,000+ encoded
    await page.goto(currentUrl + sep + 'salary=' + encodeURIComponent(minSalary));
    await page.waitForNavigation({ timeout: 15000 }).catch(() => {});
    await page.checkAntiBot({ maxWait: 10000 });
    await page.randomDelay(1500, 2500);
  }

  // Wait for job cards to load
  await page.waitForSelector('.job_seen_beacon, .jobsearch-ResultsList .result, .mosaic-provider-jobcards .result', { timeout: 10000 }).catch(() => {});
  await page.randomDelay(1000, 2000);

  // Phase 1: Extract job cards
  const jobs = await page.evaluate(() => {
    const results = [];
    const cards = document.querySelectorAll('.job_seen_beacon, .mosaic-zone .result, div[class*="cardOutline"]');

    cards.forEach(card => {
      try {
        const titleEl = card.querySelector('.jcs-JobTitle, a[class*="JobTitle"]');
        const title = titleEl ? titleEl.textContent.trim() : '';

        let url = '';
        if (titleEl) {
          const link = titleEl.tagName === 'A' ? titleEl : titleEl.closest('a');
          if (link) {
            const rawHref = link.href || '';
            // Prefer the real href; extract jk param for a clean canonical URL
            if (rawHref) {
              try {
                const parsedUrl = new URL(rawHref, 'https://ca.indeed.com');
                const jkParam = parsedUrl.searchParams.get('jk');
                url = jkParam ? 'https://ca.indeed.com/viewjob?jk=' + jkParam : rawHref;
              } catch(e) {
                url = rawHref;
              }
            } else if (link.id) {
              // Fallback: reconstruct from element id (sj_xxxx format)
              const jk = link.id.replace(/^sj_/, '');
              if (jk) url = 'https://ca.indeed.com/viewjob?jk=' + jk;
            }
          }
        }

        const companyEl = card.querySelector('[data-testid="company-name"], .companyName, .company_location .companyName, span[class*="company"]');
        const company = companyEl ? companyEl.textContent.trim() : '';

        const locationEl = card.querySelector('[data-testid="text-location"], .companyLocation, div[class*="company_location"] div[data-testid="text-location"]');
        const loc = locationEl ? locationEl.textContent.trim() : '';

        const salaryEl = card.querySelector('.salary-snippet-container, div[class*="salary"], .metadata.salary-snippet-container, [class*="SalarySnippet"], div[class*="salaryOnly"]');
        const salary = salaryEl ? salaryEl.textContent.trim() : '';

        const snippetEl = card.querySelector('.job-snippet, td.snip .job-snippet, [class*="JobSnippet"], ul[style]');
        const description = snippetEl ? snippetEl.textContent.trim() : '';

        if (title) {
          results.push({
            title,
            company,
            url,
            location: loc,
            salary,
            description,
            fullText: ''
          });
        }
      } catch (e) {
        // skip bad card
      }
    });

    return results;
  });

  // Phase 2: JD Detail Extraction
  if (_verifyMode) {
    jobs.forEach(j => { j.fullText = ''; });
  } else {
    for (let i = 0; i < jobs.length; i++) {
      try {
        // Click the job card title to open split-pane detail
        const titleSelectors = '.jcs-JobTitle, a[class*="JobTitle"]';
        const allTitles = await page.$$(titleSelectors);
        if (allTitles && allTitles.length > i) {
          const sel = typeof allTitles[i] === 'string' ? allTitles[i] : titleSelectors + `:nth-of-type(${i + 1})`;
          // Use evaluate to click the i-th title
          await page.evaluate((idx) => {
            const titles = document.querySelectorAll('.jcs-JobTitle, a[class*="JobTitle"]');
            if (titles[idx]) titles[idx].click();
          }, i);

          await page.randomDelay(1500, 3000);

          // Extract full job description from the detail panel
          const fullText = await page.evaluate(() => {
            const selectors = [
              '#jobDescriptionText',
              '.jobsearch-JobComponent-description',
              '[class*="jobDescription"]',
              '.jobsearch-jobDescriptionText',
              '#jobDescriptionText .jobsearch-JobComponent-description'
            ];
            for (const sel of selectors) {
              const el = document.querySelector(sel);
              if (el && el.textContent.trim().length > 50) {
                return el.textContent.trim();
              }
            }
            // Fallback: try the right pane
            const rightPane = document.querySelector('.jobsearch-RightPane, [class*="RightPane"], .jobsearch-ViewJobLayout--inline');
            if (rightPane) return rightPane.textContent.trim();
            return '';
          });

          jobs[i].fullText = fullText || '';
        }
      } catch (e) {
        jobs[i].fullText = '';
      }
    }
  }

  return { success: true, jobs };

} catch (error) {
  return { success: false, error: error.message || String(error) };
}

try {
  const keywords = params.keywords || '';
  const location = params.location || '';
  const jobType = params.jobType || '';
  const maxResults = params.maxResults || 30;
  const pageOffset = params.pageOffset || 0;

  const jobTypeMap = {
    'Full-time': 'F',
    'Part-time': 'P',
    'Contract': 'C',
    'Temporary': 'T',
    'Internship': 'I',
    'Volunteer': 'V',
    'Other': 'O',
  };

  const resultsPerPage = 25;
  const startOffset = pageOffset * resultsPerPage;

  const searchParams = new URLSearchParams({
    keywords: keywords,
    location: location,
    start: startOffset,
    origin: 'JOB_SEARCH_PAGE_JOB_FILTER',
  });

  const jobTypeCode = jobTypeMap[jobType];
  if (jobTypeCode) {
    searchParams.set('f_JT', jobTypeCode);
  }

  const searchUrl = `https://www.linkedin.com/jobs/search/?${searchParams.toString()}`;
  await page.goto(searchUrl);
  await page.checkAntiBot({ maxWait: 15000 });
  await page.randomDelay(1000, 2000);

  let retried = false;

  const waitForResultsOrEmpty = async () => {
    const timeout = 10000;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const cardEl = await page.$('a[href*="/jobs/view/"]');
      if (cardEl) return 'found';

      const noResults = await page.evaluate(() => {
        const body = document.body.innerText || '';
        return (
          body.includes('No matching jobs found') ||
          body.includes('No results found') ||
          body.includes('0 results') ||
          !!document.querySelector('.jobs-search-no-results-banner') ||
          !!document.querySelector('[data-test-id="jobs-search-empty-state"]')
        );
      });
      if (noResults) return 'empty';

      await page.waitForTimeout(500);
    }
    return 'timeout';
  };

  let resultState = await waitForResultsOrEmpty();

  if (resultState === 'empty' && !retried) {
    await page.screenshot();
    await page.evaluate(() => {
      const pills = Array.from(document.querySelectorAll(
        'button[aria-label*="Remove"], button[aria-label*="Clear"], .search-reusables__filter-pills-container button'
      ));
      for (const pill of pills) {
        const label = pill.getAttribute('aria-label') || pill.textContent || '';
        if (label.toLowerCase().includes('location') || pill.closest('[data-basic-filter-parameter-name="distance"]')) {
          pill.click();
          return true;
        }
      }
      return false;
    });
    await page.randomDelay(1500, 2500);
    retried = true;
    resultState = await waitForResultsOrEmpty();
  }

  if (resultState !== 'found') {
    return { success: true, jobs: [] };
  }

  // Phase 1: Scroll to lazy-load more cards
  let prevCount = 0;
  for (let scroll = 0; scroll < 5; scroll++) {
    const currentCount = await page.evaluate(() =>
      document.querySelectorAll('a[href*="/jobs/view/"]').length
    );
    if (currentCount >= maxResults) break;
    if (scroll > 0 && currentCount === prevCount) break;
    prevCount = currentCount;

    await page.evaluate(() => {
      const listContainer =
        document.querySelector('.jobs-search-results-list') ||
        document.querySelector('.scaffold-layout__list') ||
        document.querySelector('[data-view-name="job-search-results"]');
      if (listContainer) {
        listContainer.scrollTop += 1200;
      } else {
        window.scrollBy(0, 1200);
      }
    });
    await page.randomDelay(1500, 2500);
  }

  // Phase 1 Extraction — left-side card list only (Rule 1)
  const jobs = await page.$$eval('a[href*="/jobs/view/"]', (links, _max) => {
    const seen = new Set();
    const results = [];

    for (const link of links) {
      if (results.length >= _max) break;
      const href = link.href || '';
      const urlKey = href.split('?')[0];
      if (!href || seen.has(urlKey)) continue;
      seen.add(urlKey);

      const card = link.closest('li') || link.closest('[data-job-id]') || link.parentElement;

      const titleEl = link.querySelector('strong') ||
        link.querySelector('[class*="title"]') ||
        link.querySelector('span[aria-hidden="true"]') ||
        link;
      const title = (titleEl.innerText || titleEl.textContent || link.getAttribute('aria-label') || '').trim().split('\n')[0].trim();
      if (!title) continue;

      let company = '';
      const companyEl = card && (
        card.querySelector('[class*="company"]') ||
        card.querySelector('[class*="subtitle"]') ||
        card.querySelector('.artdeco-entity-lockup__subtitle') ||
        card.querySelector('span[class*="company-name"]')
      );
      if (companyEl) company = companyEl.innerText.trim().split('\n')[0].trim();

      let jobLocation = '';
      const locationEl = card && (
        card.querySelector('[class*="location"]') ||
        card.querySelector('[class*="metadata"]') ||
        card.querySelector('.job-card-container__metadata-wrapper') ||
        card.querySelector('li[class*="metadata"]')
      );
      if (locationEl) jobLocation = locationEl.innerText.trim().split('\n')[0].trim();

      let salary = '';
      let jobTypeExtracted = '';
      const employmentTypes = ['Full-time', 'Part-time', 'Contract', 'Temporary', 'Internship', 'Volunteer'];
      const metaItems = card ? Array.from(card.querySelectorAll(
        '[class*="metadata"] li, [class*="insight"] li, .job-card-container__metadata-item, li[class*="metadata"]'
      )) : [];

      for (const item of metaItems) {
        const text = (item.innerText || '').trim();
        if (!text) continue;
        if (employmentTypes.some(et => text.includes(et))) {
          const matched = employmentTypes.find(et => text.includes(et));
          if (matched && !jobTypeExtracted) jobTypeExtracted = matched;
        } else if (/\$|CA\$|€|£|¥|\/yr|\/hr|\/mo|k\b|K\b/i.test(text)) {
          if (!salary) salary = text.split('\n')[0].trim();
        }
      }

      if (!salary) {
        const salaryEl = card && (
          card.querySelector('[class*="salary"]') ||
          card.querySelector('[data-test-id*="salary"]') ||
          card.querySelector('[class*="compensation"]')
        );
        if (salaryEl) {
          const st = (salaryEl.innerText || '').trim();
          if (st && !/Full-time|Part-time|Contract/i.test(st)) salary = st.split('\n')[0].trim();
        }
      }

      let description = '';
      const descEl = card && (
        card.querySelector('[class*="snippet"]') ||
        card.querySelector('[class*="description"]')
      );
      if (descEl) description = (descEl.innerText || '').trim();

      results.push({ title, company, url: href, location: jobLocation, salary, jobType: jobTypeExtracted, description, fullText: '' });
    }
    return results;
  }, maxResults);

  // Phase 2: Full JD extraction with strict time budget
  if (!params._verifyMode) {
    // Budget: leave 40s buffer from 180s total; Phase 1 + scroll ~30s => ~110s for Phase 2
    const phase2Start = Date.now();
    const phase2Budget = 110000; // 110 seconds max for all detail fetches
    const maxPerJob = 8000;      // hard cap per job in ms

    const detailSelectors = [
      '.jobs-description__content',
      '.jobs-unified-top-card',
      '.job-view-layout',
      '[data-test-id="job-details-description"]',
      '.jobs-description',
    ];

    for (let i = 0; i < jobs.length; i++) {
      // Stop Phase 2 if budget is nearly exhausted
      if (Date.now() - phase2Start > phase2Budget) break;

      const jobStart = Date.now();

      try {
        const job = jobs[i];

        const clicked = await page.evaluate((jobUrl) => {
          const links = Array.from(document.querySelectorAll('a[href*="/jobs/view/"]'));
          for (const link of links) {
            if (link.href === jobUrl || link.href.startsWith(jobUrl.split('?')[0])) {
              (link.querySelector('strong') || link.querySelector('span[aria-hidden="true"]') || link).click();
              return true;
            }
          }
          return false;
        }, job.url);

        if (!clicked) {
          await page.goto(job.url);
          await page.checkAntiBot({ maxWait: 8000 });
        }

        // Short delay — just enough for detail pane to begin rendering
        await page.randomDelay(800, 1200);

        // Check budget again after delay
        if (Date.now() - jobStart > maxPerJob) continue;

        // Try each detail selector with a short timeout
        let detailFound = false;
        for (const sel of detailSelectors) {
          const remaining = maxPerJob - (Date.now() - jobStart);
          if (remaining <= 500) break;
          try {
            await page.waitForSelector(sel, { timeout: Math.min(2500, remaining), visible: true });
            detailFound = true;
            break;
          } catch (e) { /* try next */ }
        }

        if (detailFound) {
          const fullText = await page.evaluate(() => {
            const selectors = [
              '.jobs-description__content',
              '.jobs-description-content',
              '#job-details',
              '.jobs-description',
              '[data-test-id="job-details-description"]',
              '.job-view-layout',
            ];
            for (const sel of selectors) {
              const el = document.querySelector(sel);
              if (el) return el.innerText.trim();
            }
            const detailPane =
              document.querySelector('.jobs-search__job-details--wrapper') ||
              document.querySelector('.scaffold-layout__detail');
            return detailPane ? detailPane.innerText.trim() : '';
          });
          job.fullText = fullText;

          if (!job.salary || !job.jobType) {
            const detailMeta = await page.evaluate(() =>
              Array.from(document.querySelectorAll(
                '.jobs-unified-top-card__job-insight, .jobs-unified-top-card__metadata-item, [class*="insight"] li, [class*="metadata"] li'
              )).map(el => el.innerText.trim()).filter(Boolean)
            );
            const employmentTypes = ['Full-time', 'Part-time', 'Contract', 'Temporary', 'Internship', 'Volunteer'];
            for (const text of detailMeta) {
              if (!job.jobType && employmentTypes.some(et => text.includes(et))) {
                job.jobType = employmentTypes.find(et => text.includes(et)) || '';
              }
              if (!job.salary && /\$|CA\$|€|£|¥|\/yr|\/hr|\/mo|k\b|K\b/i.test(text)) {
                const clean = text.split('\n')[0].trim();
                if (!/Full-time|Part-time|Contract|Temporary|Internship|Volunteer/i.test(clean)) {
                  job.salary = clean;
                }
              }
            }
          }
        }
      } catch (err) {
        jobs[i].fullText = '';
      }
    }
  }

  return { success: true, jobs };

} catch (err) {
  return { success: false, error: err.message || String(err) };
}

try {
  const {
    keywords = '',
    location = '',
    jobType = '',
    minSalary = '',
    maxResults = 30,
  } = params;

  // Map human-readable jobType to Indeed's jt= parameter values
  const jobTypeMap = {
    'full-time': 'fulltime',
    'fulltime': 'fulltime',
    'full time': 'fulltime',
    'part-time': 'parttime',
    'parttime': 'parttime',
    'part time': 'parttime',
    'contract': 'contract',
    'internship': 'internship',
    'temporary': 'temporary',
    'temp': 'temporary',
    'casual': 'casual',
  };
  const mappedJobType = jobType
    ? (jobTypeMap[jobType.toLowerCase()] || jobType.toLowerCase())
    : '';

  const pageOffset = params.pageOffset || 0;
  const start = pageOffset * 10; // Indeed uses 10 results per page

  // Build search URL — always include l= to override stale cookie location
  const qp = new URLSearchParams();
  qp.set('q', keywords);
  qp.set('l', location); // empty string clears cookie-based location
  if (mappedJobType) qp.set('jt', mappedJobType);
  if (start > 0) qp.set('start', String(start));

  const searchUrl = `https://ca.indeed.com/jobs?${qp.toString()}`;

  await page.goto(searchUrl);
  await page.checkAntiBot({ maxWait: 20000 });
  await page.randomDelay(1000, 2000);

  // ── Zero-results detection ──────────────────────────────────────────────────
  const JOB_CARD = '.job_seen_beacon';
  const NO_RESULT_SELECTORS = [
    '[data-testid="no-results"]',
    '.jobsearch-NoResult',
    '.css-3z0qrk',
  ];

  try {
    const raceSelectors = [JOB_CARD, ...NO_RESULT_SELECTORS];
    await Promise.race(
      raceSelectors.map(sel =>
        page.waitForSelector(sel, { timeout: 10000, visible: true }).catch(() => null)
      )
    );
  } catch (_) { /* check below */ }

  const noResultEl = await (async () => {
    for (const sel of NO_RESULT_SELECTORS) {
      const el = await page.$(sel);
      if (el) return el;
    }
    return null;
  })();

  const cardEls = await page.$$(JOB_CARD);
  let hasResults = cardEls.length > 0 && !noResultEl;

  if (!hasResults) {
    // Attempt location-pill recovery
    const clearBtn = await page.$('[aria-label="Clear location input"], button[type="reset"]');
    if (clearBtn) {
      await page.humanClick('[aria-label="Clear location input"], button[type="reset"]');
      await page.randomDelay(400, 800);
    }
    if (location) {
      await page.humanType('#text-input-where', location);
      await page.randomDelay(600, 1200);
    }
    await page.keyboard.press('Enter');
    try {
      await page.waitForSelector(JOB_CARD, { timeout: 10000, visible: true });
      hasResults = true;
    } catch (_) {
      return { success: true, jobs: [] };
    }
  }

  // ── Scroll to load more cards ───────────────────────────────────────────────
  let prevCount = 0;
  for (let s = 0; s < 5; s++) {
    const count = await page.$$eval(JOB_CARD, els => els.length);
    if (count >= maxResults) break;
    if (count === prevCount && s > 0) break;
    prevCount = count;
    await page.evaluate(() => window.scrollBy(0, 700));
    await page.randomDelay(1500, 2500);
  }

  // ── Phase 1: Extract job card data ─────────────────────────────────────────
  const jobs = await page.$$eval(JOB_CARD, (cards, maxR) => {
    const employmentPattern = /full.?time|part.?time|contract|internship|temporary|casual|freelance/i;
    const salaryPattern = /\$|CAD|CA\$|\/hr|\/hour|\/yr|\/year|per hour|per year|salary/i;

    return cards.slice(0, maxR).map(card => {
      // Title + URL — prefer real href
      const titleLink = card.querySelector('h2.jobTitle a, .jobTitle a, h2 a[href]');
      const title = titleLink
        ? (titleLink.querySelector('span[title], span') || titleLink).textContent.trim()
        : '';
      const url = titleLink ? (titleLink.href || '') : '';

      // Company
      const companyEl = card.querySelector(
        '[data-testid="company-name"], .companyName, [class*="companyName"]'
      );
      const company = companyEl ? companyEl.textContent.trim() : '';

      // Location
      const locationEl = card.querySelector(
        '[data-testid="text-location"], .companyLocation, [class*="companyLocation"]'
      );
      const locationText = locationEl ? locationEl.textContent.trim() : '';

      // Metadata snippets — separate salary from jobType
      const snippets = Array.from(
        card.querySelectorAll(
          '[data-testid="attribute_snippet_testid"], ' +
          '.salary-snippet-container, ' +
          '.metadata.salary-snippet, ' +
          '.attribute_snippet, ' +
          '[class*="salary-snippet"], ' +
          '[class*="metadataContainer"] li, ' +
          '[class*="metadata-container"] li'
        )
      ).map(el => el.textContent.trim()).filter(Boolean);

      let salary = '';
      let jobTypeExtracted = '';

      for (const snip of snippets) {
        if (!jobTypeExtracted && employmentPattern.test(snip) && !salaryPattern.test(snip)) {
          jobTypeExtracted = snip;
        } else if (!salary && salaryPattern.test(snip) && !employmentPattern.test(snip)) {
          salary = snip;
        }
      }

      // Fallback: dedicated salary element
      if (!salary) {
        const salaryEl = card.querySelector(
          '.salary-snippet-container span, [class*="salaryText"], [data-testid="salary-snippet"]'
        );
        if (salaryEl) {
          const t = salaryEl.textContent.trim();
          if (salaryPattern.test(t) && !employmentPattern.test(t)) salary = t;
        }
      }

      // Description snippet
      const descEl = card.querySelector(
        '.job-snippet, [data-testid="job-snippet"], ul.job-snippet, [class*="snippet"]'
      );
      const description = descEl ? descEl.textContent.replace(/\s+/g, ' ').trim() : '';

      return { title, company, url, location: locationText, salary, jobType: jobTypeExtracted, description, fullText: '' };
    });
  }, maxResults);

  // ── Phase 2: Full JD extraction ────────────────────────────────────────────
  if (params._verifyMode) {
    jobs.forEach(j => (j.fullText = ''));
  } else {
    for (let i = 0; i < jobs.length; i++) {
      try {
        const job = jobs[i];
        if (!job.url) continue;

        // Click the i-th card's title to open split-pane detail
        try {
          await page.evaluate((idx) => {
            const cards = document.querySelectorAll('.job_seen_beacon');
            const link = cards[idx] && cards[idx].querySelector('h2.jobTitle a, .jobTitle a, h2 a');
            if (link) link.click();
          }, i);
        } catch (_) {
          await page.humanClick(
            `.job_seen_beacon:nth-of-type(${i + 1}) h2.jobTitle a, ` +
            `.job_seen_beacon:nth-of-type(${i + 1}) .jobTitle a`
          );
        }

        await page.randomDelay(1500, 3000);

        await page.waitForSelector(
          '#jobDescriptionText, .jobsearch-jobDescriptionText, [id*="jobDescription"]',
          { timeout: 8000, visible: true }
        );

        const fullText = await page.evaluate(() => {
          const el = document.querySelector(
            '#jobDescriptionText, .jobsearch-jobDescriptionText, [id*="jobDescription"]'
          );
          return el ? el.innerText.trim() : '';
        });

        // Enrich salary / jobType from detail panel if missing
        if (!job.salary || !job.jobType) {
          const extras = await page.evaluate(() => {
            const employmentPattern = /full.?time|part.?time|contract|internship|temporary|casual/i;
            const salaryPattern = /\$|CAD|CA\$|\/hr|\/hour|\/yr|\/year|per hour|per year/i;
            let salary = '';
            let jobType = '';
            const items = document.querySelectorAll(
              '[data-testid="job-salary"], ' +
              '[data-testid="jobsearch-JobInfoHeader-jobType"] span, ' +
              '[class*="salary"], ' +
              '[data-testid="attribute_snippet_testid"]'
            );
            for (const el of items) {
              const t = el.textContent.trim();
              if (!jobType && employmentPattern.test(t) && !salaryPattern.test(t)) jobType = t;
              if (!salary && salaryPattern.test(t) && !employmentPattern.test(t)) salary = t;
            }
            return { salary, jobType };
          });
          if (!job.salary && extras.salary) job.salary = extras.salary;
          if (!job.jobType && extras.jobType) job.jobType = extras.jobType;
        }

        job.fullText = fullText;
        await page.randomDelay(800, 1500);
      } catch (e) {
        jobs[i].fullText = '';
      }
    }
  }

  // ── Optional post-filter by minSalary ──────────────────────────────────────
  let filtered = jobs;
  if (minSalary) {
    const minNum = parseFloat(String(minSalary).replace(/[^0-9.]/g, ''));
    if (!isNaN(minNum)) {
      filtered = jobs.filter(j => {
        if (!j.salary) return false;
        const m = j.salary.match(/[\d,]+(\.\d+)?/);
        if (!m) return false;
        const salNum = parseFloat(m[0].replace(/,/g, ''));
        // Normalise hourly (<500) to annual equivalent
        const annual = salNum < 500 ? salNum * 2080 : salNum;
        const minAnnual = minNum < 500 ? minNum * 1000 : minNum;
        return annual >= minAnnual;
      });
    }
  }

  return { success: true, jobs: filtered };
} catch (err) {
  return { success: false, error: err.message };
}
